from pathlib import Path
import re
R=Path('.')
def rw(p,fn):
 s=(R/p).read_text(encoding='utf-8'); s2=fn(s); assert s2!=s, p+' was not changed'; (R/p).write_text(s2,encoding='utf-8')
# users
rw('app/src/main/assets/screens/users.html',lambda s:s.replace("function goHome(){if(bridge&&typeof bridge.goHome==='function'){try{bridge.goHome();return}catch(_){}}if(bridge&&typeof bridge.navigateTo==='function'){try{bridge.navigateTo('main');return}catch(_){}}location.href='main.html'}","function goHome(){location.href='../main.html'}",1).replace('align-items:flex-end;justify-content:center','align-items:center;justify-content:center;padding:12px;overflow:auto',1).replace('border-bottom:0;','',1))
# login
rw('app/src/main/assets/screens/login.html',lambda s:s.replace('submitBtn.focus();','',1).replace("submitBtn.style.transform = 'scale(1.02)';\n                setTimeout(() => { submitBtn.style.transform = ''; }, 300);",'',1))
# main avatar
rw('app/src/main/assets/main.html',lambda s:s.replace("if (roleEl) roleEl.textContent = user.role_name || user.role || '—';", "if (roleEl) roleEl.textContent = user.role_name || user.role || '—';\n            const avatarEl=document.getElementById('userAvatar');\n            const avatarPath=String(user.avatar_path||user.avatar||user.profile_image||'').trim();\n            if(avatarEl){if(/^(file:|content:|data:|https?:)/i.test(avatarPath)||avatarPath.startsWith('assets-local/')) avatarEl.src=avatarPath.startsWith('assets-local/')?'file:///android_asset/'+avatarPath:avatarPath;else avatarEl.src='file:///android_asset/assets-local/images/default_avatar.png';}",1))
# first setup station selector
p='app/src/main/assets/screens/first-user-setup.html';s=(R/p).read_text(encoding='utf-8');s=s.replace('<input id="stationId" type="number" required min="1" step="1" inputmode="numeric" placeholder="معرف المحطة">','<select id="stationId" required><option value="">جاري تحميل المحطات...</option></select><span class="hint" id="stationHint">يتم جلب المحطات من SQLite.</span>',1).replace('<input id="branchId" type="number" required min="1" step="1" inputmode="numeric" placeholder="معرف الفرع">','<input id="branchId" type="number" required min="1" step="1" readonly placeholder="يُعبأ تلقائياً من المحطة">',1);marker='            function getPayload(){';loader="""            async function loadStationsForSetup(){const select=document.getElementById('stationId'),branch=document.getElementById('branchId');try{if(!window.AndroidInterface||typeof window.AndroidInterface.getStations!=='function')throw new Error('عقد المحطات غير متاح.');const raw=window.AndroidInterface.getStations(),r=typeof raw==='string'?JSON.parse(raw):raw;if(r&&r.success===false)throw new Error(r.error||r.message||'تعذر جلب المحطات.');const rows=Array.isArray(r)?r:(Array.isArray(r.data)?r.data:[]);select.innerHTML='<option value=\"\">اختر المحطة</option>';rows.forEach(x=>{const id=x.id??x.station_id;if(!id)return;const o=document.createElement('option');o.value=String(id);o.textContent=x.station_name_ar||x.station_name||x.station_code||('محطة #'+id);o.dataset.branchId=x.branch_id??'';select.appendChild(o)});select.onchange=()=>{const o=select.options[select.selectedIndex];branch.value=o?.dataset.branchId||''};document.getElementById('stationHint').textContent=rows.length?'اختر المحطة وسيتم تعبئة رقم الفرع تلقائياً.':'لا توجد محطات في قاعدة البيانات.'}catch(e){select.innerHTML='<option value=\"\">تعذر تحميل المحطات</option>';document.getElementById('stationHint').textContent=e.message||'تعذر جلب المحطات.';toast(e.message||'تعذر جلب المحطات من SQLite.','error')}}\n""";assert marker in s;s=s.replace(marker,loader+marker,1);dm='                updateJobTitleOptions(); syncFullNameArabic();';assert dm in s;s=s.replace(dm,dm+'\n                loadStationsForSetup();',1);(R/p).write_text(s,encoding='utf-8')
# deliveries bridge contracts
p='app/src/main/assets/screens/deliveries.html';s=(R/p).read_text(encoding='utf-8');s=re.sub(r"invoke\(\s*'getCustomers',\s*\['\{\}'\]\s*\)","invoke('getCustomers')",s,1);s=s.replace("typeof bridge.getVehicleRecords !==","typeof bridge.getVehicles !==",1);s=re.sub(r"invoke\(\s*'getVehicleRecords',\s*\['\{\}'\]\s*\)","invoke('getVehicles')",s,1);s=re.sub(r"invoke\(\s*'updateDeliveryRecord',\s*\[\s*JSON\.stringify\(\s*payload\s*\)\s*\]\s*\)","invoke('updateDeliveryRecord',[Number(state.editingId),JSON.stringify(payload)])",s,1);s=re.sub(r"invoke\(\s*'deleteDeliveryRecord',\s*\[\s*JSON\.stringify\(\{\s*id:id\s*\}\)\s*\]\s*\)","invoke('deleteDeliveryRecord',[id])",s,1);# current shift: preserve only getCurrentShift path
s=re.sub(r"let response;\s*if \(\s*bridge &&\s*typeof bridge\.getShiftRecordsTyped ===\s*'function'\s*\) \{.*?renderShiftOptions\(\);", "let response; if(!bridge||typeof bridge.getCurrentShift!=='function') throw new Error('عقد الوردية الحالية غير متاح في Android Bridge.'); response=await invoke('getCurrentShift'); const current=dataOf(response); state.shifts=current&&current.id?[current]:(current&&current.shift_id?[current]:[]); renderShiftOptions();",s,count=1,flags=re.S);s=s.replace("id='f_id'","id='f_id' style='display:none'",1).replace("id='f_sale_id'","id='f_sale_id' style='display:none'",1);(R/p).write_text(s,encoding='utf-8')
# MainActivity: users permission blockers and dedicated fuel-sale path
p='app/src/main/java/com/aistudio/dieselstationsms/kxmpzq/MainActivity.kt';s=(R/p).read_text(encoding='utf-8');n=s.count('requireUsersPermission(');s=re.sub(r'^\s*requireUsersPermission\("(?:read|create|update|delete)"\)\s*\n','',s,flags=re.M);assert s.count('requireUsersPermission(')<=1 and n>1
s=s.replace('fun updateFuelSaleRecord(id: Long, jsonData: String) = operationalUpdate("sales", "fuel_sales", id, jsonData)', '''fun updateFuelSaleRecord(id: Long, jsonData: String): String { val a=getActivity()?:return errorResponse("النشاط غير متاح"); val db=getDbHelper()?:return errorResponse("قاعدة البيانات غير متاحة"); return try { val stationId=requireCurrentStationId(db,a.currentUserId); val rows=db.updateOperationalRecord("fuel_sales",id,operationalScopedJson(jsonData),a.currentUserId); if(rows>0)dataResponseObject(JSONObject().apply{put("success",true);put("message","تم تعديل عملية البيع فعلياً");put("record",db.getOperationalRecord("fuel_sales",id)?:JSONObject());put("station_id",stationId)}).toString() else successResponse(false,"لم يتم العثور على عملية البيع") } catch(e:Exception){DebugLogger.logException("UpdateFuelSaleRecord",e);errorResponse(e.message?:"فشل تعديل عملية البيع")} }''',1)
s=s.replace('fun deleteFuelSaleRecord(id: Long) = operationalDelete("sales", "fuel_sales", id)', '''fun deleteFuelSaleRecord(id: Long): String { val a=getActivity()?:return errorResponse("النشاط غير متاح"); val db=getDbHelper()?:return errorResponse("قاعدة البيانات غير متاحة"); return try { val stationId=requireCurrentStationId(db,a.currentUserId); val rows=db.deleteOperationalRecord("fuel_sales",id,a.currentUserId,stationId); successResponse(rows>0,if(rows>0)"تم إلغاء/أرشفة عملية البيع فعلياً" else "لم يتم العثور على عملية البيع") } catch(e:Exception){DebugLogger.logException("DeleteFuelSaleRecord",e);errorResponse(e.message?:"فشل إلغاء عملية البيع")} }''',1);(R/p).write_text(s,encoding='utf-8')
print('repairs complete')
